def preparar_inventario_trazable(apps, schema_editor):
    Consumible = apps.get_model('webcitt', 'Consumible')
    EntradaInventario = apps.get_model('webcitt', 'EntradaInventario')
    LoteConsumible = apps.get_model('webcitt', 'LoteConsumible')

    EntradaInventario.objects.filter(motivo='', tipo='ingreso').update(motivo='recepcion')
    EntradaInventario.objects.filter(motivo='', tipo='salida').update(motivo='consumo_produccion')

    for consumible in Consumible.objects.filter(stock_total__gt=0).iterator():
        LoteConsumible.objects.get_or_create(
            consumible_id=consumible.pk,
            codigo='SALDO-INICIAL',
            defaults={
                'cantidad_inicial': consumible.stock_total,
                'cantidad_actual': consumible.stock_total,
                'estado': 'bodega',
                'bodega': consumible.ubicacion or 'Ubicación histórica por confirmar',
                'fecha_vencimiento': consumible.fecha_vencimiento,
                'costo_unitario': consumible.precio_unitario,
                'documento_recepcion': 'Migración de existencia inicial',
                'observaciones': (
                    'Saldo existente antes de habilitar el seguimiento individual por lotes.'
                ),
            },
        )


